import{_ as a,c as s,a2 as l,o as i}from"./chunks/framework.Dz7_3PEu.js";const n="/assets/image-20250108163755825.CymJqye7.png",k=JSON.parse('{"title":"共识过程","description":"","frontmatter":{},"headers":[],"relativePath":"source/consensus/consensus.md","filePath":"source/consensus/consensus.md","lastUpdated":1736756758000}'),o={name:"source/consensus/consensus.md"};function r(t,e,p,c,d,h){return i(),s("div",null,e[0]||(e[0]=[l('<h1 id="共识过程" tabindex="-1">共识过程 <a class="header-anchor" href="#共识过程" aria-label="Permalink to &quot;共识过程&quot;">​</a></h1><h2 id="前置共识和后置共识是什么" tabindex="-1">前置共识和后置共识是什么？ <a class="header-anchor" href="#前置共识和后置共识是什么" aria-label="Permalink to &quot;前置共识和后置共识是什么？&quot;">​</a></h2><p><strong>前置共识</strong>包括了晶格自研优化的PoA，主要是对上链数据的节点进行了循环排序设置，确保当前节点出问题，仍然有候补节点接替数据上链的工作，不会导致上链失败。<strong>后置共识</strong>是自研的一种基于BFT的见证共识机制，主要是让见证节点对上链的数据进行投票验证，超过三分之二个节点确认后的数据，就再也无法篡改，在链上锚定。</p><h2 id="共识的流程-交易从发起到被确认的过程" tabindex="-1">共识的流程（交易从发起到被确认的过程） <a class="header-anchor" href="#共识的流程-交易从发起到被确认的过程" aria-label="Permalink to &quot;共识的流程（交易从发起到被确认的过程）&quot;">​</a></h2><ol><li>用户发起一笔交易（TBlock）到peer1</li><li>peer1验证并广播这笔交易和签名给peer i</li><li>peer i 验证交易并广播签名</li><li>peer i 收集到大于2/3共识节点数量的签名后TBlock放入TBpool</li><li>前置共识选出当前高度的DBlock的出块者 peer 2（peer2可以与peer1为同一节点）</li><li>peer2 在打包区块时引用已经确认的TBlock的hash, 生产DBlock1</li><li>peer2 在等待规定的period时间后验证并广播DBlock1</li><li>peer i 验证DBlock1，广播签名</li><li>peer i 收集到大于2/3共识节点数量的签名后，DBlock1确认，其引用（守护）的TBlock也被最终确认</li></ol><p>下图为DBlock共识示意图，TBlock无需miner（前置共识）其余流程相同</p><p><img src="'+n+`" alt="image-20250108163755825"></p><h2 id="分叉" tabindex="-1">分叉 <a class="header-anchor" href="#分叉" aria-label="Permalink to &quot;分叉&quot;">​</a></h2><h3 id="分叉的产生" tabindex="-1">分叉的产生 <a class="header-anchor" href="#分叉的产生" aria-label="Permalink to &quot;分叉的产生&quot;">​</a></h3><p>在step5中如果按规则选出的peer并没有按预期打包区块并广播（在p2p网络中表现为：当前节点未在△内收到当前高度的区块）, 那么当前节点会成为miner打包并广播区块，由此会产生分叉。</p><h3 id="分叉的处理" tabindex="-1">分叉的处理 <a class="header-anchor" href="#分叉的处理" aria-label="Permalink to &quot;分叉的处理&quot;">​</a></h3><p>在产生分叉之后，每个节点会将先收到的区块或签名数量较多的区块作为mainBlock</p><div class="language-golang vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">golang</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if br.MainBlock == nil || len(br.MainBlock.GetSigners()) &lt; len(wb.GetSigners()) {</span></span>
<span class="line"><span>    br.MainBlock = wb</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在后续，会在mainBlock的基础上继续出块。</p><ol><li>如果在后续高度上仍然收到了多个区块且这些区块的签名都不大于2/3，用同样的方法在分叉上继续追加。</li><li>如果在某个高度上收到某区块其签名数量大于2/3，则以该区块的引用结束分叉。</li></ol>`,15)]))}const m=a(o,[["render",r]]);export{k as __pageData,m as default};
